import{_ as n,a0 as s,w as p,s as u,ao as o,I as i,x as t,a1 as r,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"衡量你的開源軟件使用情況的 8 個方法 | LCTT x X-CMD","titleTemplate":false,"description":"衡量你的開源軟件使用情況的 8 個方法 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"衡量你的開源軟件使用情況的 8 個方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"衡量你的開源軟件使用情況的 8 個方法 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221202.0 ⭐️⭐️ 8 ideas for measuring your open source software usage","title":"衡量你的開源軟件使用情況的 8 個方法","tag":"202301","desc":""},"relativePath":"202301/20221202.0 ⭐️⭐️ 8 ideas for measuring your open source software usage.md","filePath":"[post].md"}'),d={name:"202301/20221202.0 ⭐️⭐️ 8 ideas for measuring your open source software usage.md"};function m(f,l,b,x,T,g){const e=s("Link");return p(),u("div",null,[l[25]||(l[25]=o('<h1 id="衡量你的開源軟件使用情況的-8-個方法" tabindex="-1">衡量你的開源軟件使用情況的 8 個方法 <a class="header-anchor" href="#衡量你的開源軟件使用情況的-8-個方法" aria-label="Permalink to “衡量你的開源軟件使用情況的 8 個方法”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202301/04/173129vmnstoxnzmjlnsxw.jpg" alt=""></p><blockquote><p>想知道如何為你的開源軟件項目收集使用指標？考慮一下使用這些替代方案的利弊。</p></blockquote><p>我們這些支持開源項目社區的人經常被問到很多有關使用指標的問題。這些指標通常是為了通過用户量和知名度來衡量軟件的重要性。我們一般都想知道有多少人使用該軟件，有多少次安裝，以及有多少人生活接觸過它。</p><p>但簡而言之，我們尚無法直接回答上述問題。</p><p>如果你想要尋找一個明確的解決方案，那很抱歉要讓你失望了。有關使用指標的問題，沒有人有完美的答案，至少沒有準確的答案。</p><p>好消息是，有一些近似的和替代指標至少能夠部分地滿足你對軟件使用情況瞭解的渴求。本文探討了這些替代方案以及它們的優點和缺點。</p><h3 id="下載量" tabindex="-1">下載量 <a class="header-anchor" href="#下載量" aria-label="Permalink to “下載量”">​</a></h3><p>當你瀏覽提供軟件的網站時，你通常可以看到軟件的下載次數。映入我腦海的一個例子是 Firefox ，它曾經有一個下載計數器。Firefox 的下載量是一個印象深刻的數字，給人的印象是 Firefox 是一個流行的瀏覽器，在一段時間內確實如此。</p><p>然而，個人行為會直接影響這一數字的準確性。舉例而言，當一個人定期重置他們的設備時，每一次重建都會引發一次獨立的下載。考慮到這一現實，需要設計一種方法從下載量中去除幾十次（或許是幾百次）的下載次數，因為那是一個人。</p><p>下載量不僅會高估使用量，還會低估使用量。例如，一個系統管理員可能會下載一個新版本的 Firefox 一次並將其拷貝到 U 盤上，然後安裝到數百台設備上。</p><p>下載量指標是易於收集的，你可以在服務器上記錄每一個下載請求。問題在於你不知道在這些軟件下載以後會發生什麼。下載它的人是否如預期的那樣使用軟件，還是遇到了問題而放棄了它。</p><p>對於開源項目而言，你可以考慮各種下載量指標，比如來自以下途徑的下載指標：</p><ul><li>項目官網</li><li>包管理器，比如 npm、PyPi 和 Maven</li><li>代碼倉庫，如 GitHub、GitLab、Gitee 等</li></ul>',14)),i("p",null,[l[1]||(l[1]=t("你可能還對源代碼的下載量感興趣，因為下游項目更可能使用源代碼形式（參見 ",-1)),r(e,{href:"https://opensource.com/article/18/5/metrics-project-success"},{default:a(()=>[...l[0]||(l[0]=[t("《如何衡量你的開源項目的影響》",-1)])]),_:1}),l[2]||(l[2]=t("一文）。相應的下載指標包括：",-1))]),l[26]||(l[26]=i("ul",null,[i("li",null,"從代碼倉庫克隆的數量，比如 GitHub、GitLab 和 Gitee"),i("li",null,"從官網下載的歸檔文件（tar、zip）的數量"),i("li",null,"通過像 npm、PyPi 和 Maven 這樣的包管理器下載的源代碼數量")],-1)),l[27]||(l[27]=i("p",null,"源代碼的下載指標比二進制代碼的下載指標更不可靠（雖然尚無相關研究表明如此）。試想一下，一名開發人員想要你的最新版本的源代碼，並將他們的構建管道配置為每次構建都克隆你的倉庫。再想像一下，一個自動構建過程失敗了，它試圖重新構建而不斷地克隆你的版本庫。你還可以考慮這樣一個下載量低於預期的場景——源代碼倉庫在某些地方緩存了，下載來源是由這些緩存所提供的。",-1)),i("blockquote",null,[i("p",null,[i("strong",null,[r(e,{href:"https://opensource.com/article/22/11/community-metrics"},{default:a(()=>[...l[3]||(l[3]=[t("相關閲讀：跟蹤你的開源社區的 5 個指標",-1)])]),_:1})])])]),l[28]||(l[28]=o('<p>總而言之，下載量指標是用於提供當前使用情況和探測趨勢的很好的指徵。我們無法明確地定義一次下載是如何轉化為使用的。不過我們可以認為增加的下載量是更多潛在用户的標誌。舉例而言，如果你為你的軟件做了廣告並在活動期間得到了更高的下載量，可以合理地假定廣告推動了更多人下載該軟件。下載行為的來源與元數據還可以提供額外的與使用行為相關的內容。你的軟件的哪些版本仍在使用中？什麼操作系統或者特定語言的版本更加流行？這有助於社區決定將哪個平台的軟件作為支持與測試的優先選項。</p><h3 id="議題" tabindex="-1">議題 <a class="header-anchor" href="#議題" aria-label="Permalink to “議題”">​</a></h3><p>作為一個開源項目，你可能有一個議題追蹤器。當某個人提出一個議題時一般有兩個目標，報告一個漏洞或者請求增加一項功能。提議者很可能已經使用過你的軟件了。作為一名用户，他可能發現了一個漏洞或者發現了對一個新功能的需求。</p><p>很明顯，大多數用户不會執行額外的步驟來提交議題。提議者是我們的忠實用户，我們對他們表示感謝。此外，通過提出議題，他們已經成為了非代碼貢獻者，他們也有希望成為代碼貢獻者。經驗法則是大約每 10000 名用户中，可能有 100 名提議者，以及 1 名代碼貢獻者。當然取決於用户類型，上述比例可能有出入。</p><p>回到指標問題，你可以將提議者數量作為評估使用量的下界。相關的指標包括：</p><ul><li>提議者數量</li><li>活躍提議者的數量（在過去 6 個月內提出議題的提議者）</li><li>同時有代碼貢獻的提議者的數量</li><li>尚未解決的議題的數量</li><li>對議題發佈的評論數量</li></ul><h3 id="郵件列表、論壇和問答網站" tabindex="-1">郵件列表、論壇和問答網站 <a class="header-anchor" href="#郵件列表、論壇和問答網站" aria-label="Permalink to “郵件列表、論壇和問答網站”">​</a></h3><p>很多開源項目都擁有用户郵件列表、論壇，並且出現在類似 Stack Overflow 的問答網站上。與提問者一樣，在這些地方發帖的人可被視作用户的冰山一角。與郵件列表、論壇和問答網站上的社區活躍程度相關的指標也可用於反映用户數量的上升或下降。相關指標可以集中於以下地方的活動，包括：</p><ul><li>用户郵件列表的訂閲量</li><li>論壇用户的數量</li><li>問題的數量</li><li>答案的數量</li><li>發佈信息的數量</li></ul><h3 id="上報功能" tabindex="-1">上報功能 <a class="header-anchor" href="#上報功能" aria-label="Permalink to “上報功能”">​</a></h3><p>為了獲得精確的用户數量，一個方案是讓軟件在使用時上報信息。</p><p>這是令人毛骨悚然的。想像一下，系統管理員的防火牆報告了一個非預期的到你的服務器的網絡連接，你不僅無法再收到軟件報告（被防火牆攔截了），恐怕連你的軟件也可能在未來被禁止使用。</p><p>負責任的設置上報功能的方式為設置一項可選服務來檢查更新並讓用户知道使用最新版本。另一項可選功能可以集中在使用遙測上，你可以通過該功能詢問用户是否允許匿名上報軟件使用情況。如果經過深思熟慮的實施，這種方式可以允許用户通過他們使用軟件的方式幫助優化軟件。用户可以持有這樣的意見：我一般不允許這種使用信息的分享；但對於一些軟件，因為希望開發人員在長期內將軟件優化得更好，我願意這樣做。</p><h3 id="星標與復刻" tabindex="-1">星標與復刻 <a class="header-anchor" href="#星標與復刻" aria-label="Permalink to “星標與復刻”">​</a></h3><p>星標與復刻是如 GitHub、GitLab、Gitee 等社交化編程平台的功能。這些平台上的用户可以給一個項目加星標。為什麼他們要給項目加星標呢？GitHub 的文檔作出瞭解釋：你可以給一個倉庫和主題加星標，以跟蹤感興趣的項目，和在你的新聞訂閲中發現相關的內容。給一個項目加星標與將其加入書籤的效果一樣，並且還提供了一種向項目倉庫的維護者展示讚賞的方式。星標的數量已經成為了項目流行程度的標誌。當一個項目發佈重大公告並獲得相當的關注時，項目的星標數量會呈上升趨勢。星標的數量指標並不反映軟件的使用量。</p><p>在社交化編程平台上的<ruby>復刻<rt>Fork</rt></ruby>是將項目倉庫複製一份在自己名下。倉庫的非維護者可以在他們自己的克隆倉庫中做修改，並將修改通過<ruby>拉取請求<rt>pull request</rt></ruby>（PR）的方式提交審核。復刻比星標更能反映軟件社區的規模。開發者也可能為了保存一份代碼副本而克隆一個項目，以便在原始倉庫消失後他們仍能訪問代碼。因為復刻功能在代碼貢獻工作流中的應用，復刻量是衡量開發社區的良好指標。復刻量通常也不反映非開發人員的使用，因為非開發人員一般不創建復刻。</p><h3 id="社交媒體" tabindex="-1">社交媒體 <a class="header-anchor" href="#社交媒體" aria-label="Permalink to “社交媒體”">​</a></h3><p>包括 Facebook、Instagram、LinkIn、Reddit、Twtter 等社交媒體平台提供了相同興趣的人們聚集的平台。採用社交媒體策略，開源項目可以通過在平台上設置相應的聚集空間來吸引對項目感興趣的人們。通過這些社交媒體途徑，開源項目可以分享項目新聞、更新，指出貢獻者和用户。這些社交媒體途徑還可以用於認識那些本不會通過其他途徑與項目互動的人。</p><p>我在猶豫是否建議關注以下指標，因為它與軟件的真實使用量沒有清晰的聯繫，並通常需要分析其中的積極、消極和中性的情緒。人們可能因為很多不同的原因對你的項目感到激動而關注它，但並不實際使用它。然而與之前已經討論過的指標一樣，能夠在社交媒體上吸收人羣本就是項目受關注的整體指標。不同社交媒體平台的指標包括：</p><ul><li>關注者與訂閲者的數量</li><li>消息的數量</li><li>活躍的消息作者的數量</li><li>喜歡、分享、回覆以及其他交互的數量</li></ul><h3 id="網站分析與文檔" tabindex="-1">網站分析與文檔 <a class="header-anchor" href="#網站分析與文檔" aria-label="Permalink to “網站分析與文檔”">​</a></h3><p>網站流量也是一個有用的指標。這一指標主要受到你的服務範圍以及市場營銷活動影響，而不是用户量。然而，我們還有一張王牌：我們的用户文檔、教程、手冊以及 API 文檔。我們可以發現我們的網站以及文檔中的什麼主題更引人注意。文檔的訪問者數量應當大致隨着軟件的使用者數量增長而增長。因此我們可以通過網站的訪問量探知對項目的普遍興趣，並進一步通過觀察文檔的訪問者來觀察用户風向。這些指標包括：</p><ul><li>網站訪問者數量</li><li>文檔訪問者的數量</li><li>訪問者在你的網站與文檔上所花的時間</li></ul><h3 id="活動" tabindex="-1">活動 <a class="header-anchor" href="#活動" aria-label="Permalink to “活動”">​</a></h3><p>活動的指標可以在你主持與項目相關的活動時使用。這是建立社區的很好的方式。有多少人提交摘要想要在你的活動中發言？有多少人出席你的活動？不論是在線下活動還是線上活動這可能都很有趣。當然，你如何推廣你的活動在很大程度上決定有多少人到場。同時你可以將自己的活動與人們出行的大型活動放在一起以方便人們參加你的活動。只要你使用一貫的活動策略，你可以通過演講者提交的材料與參會者註冊的增加來表徵軟件受歡迎程度與用户羣的增加。</p>',25)),i("p",null,[l[5]||(l[5]=t("你並不需要舉辦你自己的活動來收集有用的指標。如果你在開源活動中主持有關你項目的討論，你可以衡量有多少人出席主要關注你的項目的會議。像 ",-1)),r(e,{href:"https://fosdem.org/"},{default:a(()=>[...l[4]||(l[4]=[t("FOSDEM",-1)])]),_:1}),l[6]||(l[6]=t(" 這樣的活動，一些討論特別聚焦於開源項目的更新與發佈，會議室中都擠滿了人（像 FOSDEM 的所有會議一樣）。",-1))]),l[29]||(l[29]=i("p",null,"你可以考慮如下指標:",-1)),l[30]||(l[30]=i("ul",null,[i("li",null,"以你的項目為中心的活動的出席人數"),i("li",null,"提交到以你的項目為中心的活動的演講數量"),i("li",null,"以你的項目為中心的演講的出席人數")],-1)),l[31]||(l[31]=i("h3",{id:"關於估算開源軟件使用的結論",tabindex:"-1"},[t("關於估算開源軟件使用的結論 "),i("a",{class:"header-anchor",href:"#關於估算開源軟件使用的結論","aria-label":"Permalink to “關於估算開源軟件使用的結論”"},"​")],-1)),l[32]||(l[32]=i("p",null,"正如我們已經如上展現的，有很多指標可以反映軟件使用的趨勢，沒有一個指標是完美的。在大多數情況下，這些指標可能被個人行為、系統設計和噪音所嚴重影響。因此，考慮到每一個指標的相對不確定性，我們建議你不要孤立地使用任何一個指標。但是如果你從不同的來源收集了一系列的指標，你應當能夠探測到用户行為與軟件使用的趨勢。如果你有辦法在多個具有共性的開源項目中比較同一組指標，例如類似的功能、強大的相互依賴性、在同一基礎設施上託管，以及其他特徵，你就可以提升你對用户行為基線的感知。",-1)),l[33]||(l[33]=i("p",null,"需要注意的是，在這篇概述中，我們選擇突出能夠評估直接使用情況的指標。而大多數軟件都依賴於其他各種軟件包，如果我們不提及作為軟件依賴鏈的一部分而被間接使用的嚴重影響，這就是我們的疏忽。因此，我們建議將上下游依賴的合計數量作為你的分析中的另一層內容。",-1)),l[34]||(l[34]=i("p",null,"最後，作為數據與指標的使用者，我們鼓勵你認識到你的利益相關方的權利與責任。你發佈的任何指標都有可能影響用户行為。最好的做法是經常一同分享你的背景信息——基礎、來源、估算方法和其他關鍵上下文信息，這有助於其他人解釋你的結果。",-1)),i("p",null,[l[8]||(l[8]=t("感謝 ",-1)),r(e,{href:"https://chaoss.community"},{default:a(()=>[...l[7]||(l[7]=[t("CHAOSS",-1)])]),_:1}),l[9]||(l[9]=t(" 社區在愛爾蘭都柏林舉行的 CHAOSScon EU 2022 上的富有洞察力的對話，上述對話激發這篇博文的想法。我們還要感謝 CHAOSS 社區的成員審閲並幫助優化本文。",-1))]),l[35]||(l[35]=i("hr",null,null,-1)),i("p",null,[l[11]||(l[11]=t("via: ",-1)),r(e,{href:"https://opensource.com/article/22/12/open-source-usage-metrics"},{default:a(()=>[...l[10]||(l[10]=[t("https://opensource.com/article/22/12/open-source-usage-metrics",-1)])]),_:1})]),i("p",null,[l[16]||(l[16]=t("作者：",-1)),r(e,{href:"https://opensource.com/users/georglink"},{default:a(()=>[...l[12]||(l[12]=[t("Georg Link, Sophia Vargas",-1)])]),_:1}),l[17]||(l[17]=t(" 選題：",-1)),r(e,{href:"https://github.com/lkxed"},{default:a(()=>[...l[13]||(l[13]=[t("lkxed",-1)])]),_:1}),l[18]||(l[18]=t(" 譯者：",-1)),r(e,{href:"https://github.com/CanYellow"},{default:a(()=>[...l[14]||(l[14]=[t("CanYellow",-1)])]),_:1}),l[19]||(l[19]=t(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:a(()=>[...l[15]||(l[15]=[t("wxy",-1)])]),_:1})]),i("p",null,[l[22]||(l[22]=t("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...l[20]||(l[20]=[t("LCTT",-1)])]),_:1}),l[23]||(l[23]=t(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:a(()=>[...l[21]||(l[21]=[t("Linux中國",-1)])]),_:1}),l[24]||(l[24]=t(" 榮譽推出",-1))])])}const S=n(d,[["render",m]]);export{P as __pageData,S as default};
